# GymSite Distance Matrix - PowerShell Installer
# Execute em: C:\Users\marce\gymsite_intelligence
# Comando: powershell -ExecutionPolicy Bypass -File install_distance_matrix.ps1

$base="C:\Users\marce\gymsite_intelligence"
New-Item -ItemType Directory -Force "$base\tools\cache\distance_matrix" | Out-Null
New-Item -ItemType Directory -Force "$base\tests" | Out-Null

# apply_patches.py
$xapply_patches_py=""
[IO.File]::WriteAllBytes("$base\apply_patches.py",[Convert]::FromBase64String($xapply_patches_py))
Write-Host "OK: apply_patches.py"

# tests/test_distance_matrix.py
$xtests_test_distance_matrix_py=""
[IO.File]::WriteAllBytes("$base\tests\\test_distance_matrix.py",[Convert]::FromBase64String($xtests_test_distance_matrix_py))
Write-Host "OK: tests/test_distance_matrix.py"

# tools/distance_matrix_tools.py
$xtools_distance_matrix_tools_py=""
[IO.File]::WriteAllBytes("$base\tools\\distance_matrix_tools.py",[Convert]::FromBase64String($xtools_distance_matrix_tools_py))
Write-Host "OK: tools/distance_matrix_tools.py"

Write-Host ""
Write-Host "Concluido! Proximos passos:"
Write-Host "  1. pip install googlemaps"
Write-Host "  2. Adicionar GOOGLE_DISTANCE_MATRIX_API_KEY no .env"
Write-Host "  3. python apply_patches.py"
Write-Host "  4. python -m pytest tests/test_distance_matrix.py -v"